using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CoastalNeedlePineDetail {
const string D="Assets/Scenes/Oasis/CoastalTerrain/Details";static CoastalNeedlePineDetail(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoastalNeedlePineDetail.request"))return;try{File.Delete("CoastalNeedlePineDetail.request");}catch(IOException){return;}Run();}
static void Run(){try{string path=D+"/Fine Needle Forest Pine.png";var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.alphaIsTransparency=true;imp.npotScale=TextureImporterNPOTScale.None;imp.mipmapEnabled=true;imp.mipMapsPreserveCoverage=true;imp.alphaTestReferenceValue=.2f;imp.streamingMipmaps=true;imp.filterMode=FilterMode.Trilinear;imp.anisoLevel=4;imp.wrapMode=TextureWrapMode.Clamp;imp.maxTextureSize=2048;foreach(var platform in new[]{"Android","iPhone"})imp.SetPlatformTextureSettings(new TextureImporterPlatformSettings{name=platform,overridden=true,maxTextureSize=2048,format=TextureImporterFormat.ASTC_4x4,compressionQuality=90});imp.SaveAndReimport();var mat=AssetDatabase.LoadAssetAtPath<Material>(D+"/Shared mountain pine.mat");mat.SetTexture("_Atlas",AssetDatabase.LoadAssetAtPath<Texture2D>(path));mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(path));mat.SetColor("_Tint",new Color(.98f,1,.98f));mat.SetFloat("_Cutoff",.2f);EditorUtility.SetDirty(mat);int count=0;foreach(string guid in AssetDatabase.FindAssets("t:Mesh",new[]{D})){var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(AssetDatabase.GUIDToAssetPath(guid));string file=Path.GetFileName(AssetDatabase.GUIDToAssetPath(guid));if((!file.StartsWith("Pine_")&&!file.StartsWith("Pine "))||file.Contains("trunk")||mesh.name.Contains("Needle texture"))continue;var uv=mesh.uv;for(int start=0;start<uv.Length;){int stride=file.Contains("distant")?6:10;int end=Math.Min(start+stride,uv.Length);float min=uv.Skip(start).Take(end-start).Min(v=>v.x),max=uv.Skip(start).Take(end-start).Max(v=>v.x);for(int i=start;i<end;i++)uv[i]=new Vector2(Mathf.Lerp(.005f,.995f,Mathf.InverseLerp(min,max,uv[i].x)),Mathf.Lerp(.005f,.995f,Mathf.InverseLerp(.32f,.995f,uv[i].y)));start=end;}mesh.uv=uv;mesh.name+=" Needle texture";EditorUtility.SetDirty(mesh);count++;}AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Fine-Needle-Forest-Pines"});File.WriteAllText("FinalEnvironmentRoadReview/FineNeedlePineReport.txt","SUCCESS updated pine meshes="+count+"; dedicated fine needle alpha texture, coverage mipmaps, ASTC4x4; wind and prefab trunk/branch LODs retained; shader errors="+ShaderUtil.GetShaderMessages(mat.shader).Count(m=>m.severity.ToString()=="Error"));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/FineNeedlePineReport.txt","FAILED "+e);Debug.LogException(e);}}
